mapper.select:
SELECT
REGIST_SEQNO registSeqno,
SALER_REW_PENA_NO salerRewPenaNo,
SALER_INST_CODE salerInstCode,
SALER_INS_NO salerInsNo,
SALER_REW_PENA_TYEP salerRewPenaTyep,
SALER_REW_PENA_NAME salerRewPenaName,
SALER_REW_PENA_COMMENTS salerRewPenaComments,
SALER_REW_PENA_INST salerRewPenaInst,
SALER_REW_PENA_INST_NAME salerRewPenaInstName,
SALER_REW_PENA_START salerRewPenaStart,
SALER_REW_PENA_END salerRewPenaEnd,
SALER_COMPLAIN_DETAIL salerComplainDetail,
SALER_COMPLAIN_RESULT salerComplainResult,
SALER_COMPLAIN_DATE salerComplainDate,
SEND_STATUS sendStatus,
SUBMIT_FEEDBACK_MSG submitFeedbackMsg,
SUBMIT_FEEDBACK_STATUS submitFeedbackStatus,
SUBMIT_TIME submitTime,
CHB_SUBMIT_DEADLINE chbSubmitDeadline,
SUBMIT_DEADLINE submitDeadline,
STATUS status,
SUMIT_SEQ sumitSeq,
DATA_DATE dataDate,
UPDATE_TIME
FROM
CHB_SALER_REW_PENA_SUB
where 1=1

    and SALER_REW_PENA_TYEP = #{salerRewPenaTyep}


    and SALER_REW_PENA_INST = #{salerRewPenaInst}


    and SUBMIT_FEEDBACK_STATUS = #{submitFeedbackStatus}


    and SEND_STATUS = #{sendStatus}



        #{status}



    and CHB_SUBMIT_DEADLINE between STR_TO_DATE(#{searchSubmitDeadlineStart,jdbcType=VARCHAR},'%Y-%m-%d') and STR_TO_DATE(#{searchSubmitDeadlineEnd,jdbcType=VARCHAR},'%Y-%m-%d')


    and   DATE_FORMAT(DATA_DATE,'%Y-%m-%d')>= #{searchDataDateStart,jdbcType=VARCHAR}


    and   DATE_FORMAT(DATA_DATE,'%Y-%m-%d') <= #{searchDataDateEnd,jdbcType=VARCHAR}


    and   DATE_FORMAT(SUBMIT_TIME,'%Y-%m-%d')>= #{searchSubmitTimeStart,jdbcType=VARCHAR}


    and   DATE_FORMAT(SUBMIT_TIME,'%Y-%m-%d')<= #{searchSubmitTimeEnd,jdbcType=VARCHAR}


    and   DATE_FORMAT(SALER_REW_PENA_START,'%Y-%m-%d')>= #{searchSalerRewPenaStartStart,jdbcType=VARCHAR}


    and   DATE_FORMAT(SALER_REW_PENA_START,'%Y-%m-%d') <= #{searchSalerRewPenaStartEnd,jdbcType=VARCHAR}


    and   DATE_FORMAT(SALER_COMPLAIN_DATE,'%Y-%m-%d')>= #{searchSalerComplainDateStart,jdbcType=VARCHAR}


    and   DATE_FORMAT(SALER_COMPLAIN_DATE,'%Y-%m-%d') <= #{searchSalerComplainDateEnd,jdbcType=VARCHAR}

ORDER BY UPDATE_TIME DESC

