mapper.update:
update CHB_SALER_REW_PENA_SUB
SEND_STATUS = '01', SUBMIT_TIME = null, SUBMIT_FEEDBACK_STATUS = null
trim(REGIST_SEQNO) = #{dto.registSeqno}

mapper.insert:
insert into CHB_SALER_REW_PENA_SUB ( REGIST_SEQNO, SALER_REW_PENA_NO,SALER_INST_CODE,SALER_INS_NO, SALER_REW_PENA_TYEP,SALER_REW_PENA_NAME,SALER_REW_PENA_COMMENTS,SALER_REW_PENA_INST, SALER_REW_PENA_INST_NAME,SALER_REW_PENA_START,SALER_REW_PENA_END,SALER_COMPLAIN_DETAIL, SALER_COMPLAIN_RESULT,SALER_COMPLAIN_DATE, STATUS,CHB_SUBMIT_DEADLINE,SUBMIT_DEADLINE, DATA_DATE,SUBMIT_TIME,SUMIT_SEQ, SEND_STATUS, SUBMIT_FEEDBACK_STATUS,SUBMIT_FEEDBACK_MSG,CREATE_DEPT,ORG_CODE, CREATE_USER,CREATE_TIME,UPDATE_USER,UPDATE_TIME) select HIS_NO, SALER_REW_PENA_NO,SALER_INST_CODE,SALER_INS_NO, SALER_REW_PENA_TYEP,SALER_REW_PENA_NAME,SALER_REW_PENA_COMMENTS,SALER_REW_PENA_INST, SALER_REW_PENA_INST_NAME,SALER_REW_PENA_START,SALER_REW_PENA_END,SALER_COMPLAIN_DETAIL, SALER_COMPLAIN_RESULT,SALER_COMPLAIN_DATE, STATUS,CHB_SUBMIT_DEADLINE,SUBMIT_DEADLINE, DATA_DATE,SUBMIT_TIME,SUMIT_SEQ, SEND_STATUS, SUBMIT_FEEDBACK_STATUS,SUBMIT_FEEDBACK_MSG,CREATE_DEPT,ORG_CODE, CREATE_USER,his.CREATE_TIME,UPDATE_USER,UPDATE_TIME from CHB_SALER_REW_PENA_SUB_HIS his INNER join ( SELECT max(CREATE_TIME) CREATE_TIME from CHB_SALER_REW_PENA_SUB_HIS
SALER_REW_PENA_NO IN
#{regist.salerRewPenaNo,jdbcType=VARCHAR}
) maxtime on his.CREATE_TIME=maxtime.CREATE_TIME
SALER_REW_PENA_NO IN
#{regist.salerRewPenaNo,jdbcType=VARCHAR}

mapper.delete:
delete from CHB_SALER_REW_PENA_SUB_HIS where CREATE_TIME=( SELECT T.CREATE_TIME FROM ( SELECT max(CREATE_TIME) CREATE_TIME from CHB_SALER_REW_PENA_SUB_HIS
SALER_REW_PENA_NO IN
#{regist.salerRewPenaNo,jdbcType=VARCHAR}
)T)
and SALER_REW_PENA_NO IN
#{regist.salerRewPenaNo,jdbcType=VARCHAR}

